// Select random gallery image
const galleryImages = [
  { file: 'alfie_border_collie_portrait_2048x2048.webp', animal: 'Border Collie', breed: 'Border Collie', style: 'Ink Wash' },
  { file: 'alfie_imperial_portrait_2048x2048.webp', animal: 'Border Collie', breed: 'Border Collie', style: 'Chinese Classical' },
  { file: 'alfie_portrait_final.webp', animal: 'Border Collie', breed: 'Border Collie', style: 'Pixar 3D' },
  { file: 'border_collie_portrait_2048x2048.webp', animal: 'Border Collie', breed: 'Border Collie', style: 'Needle Felt' },
  { file: 'cat_vermeer.webp', animal: 'Cat', breed: 'Cat', style: 'Renaissance' },
  { file: 'chihuahua_portrait_16x9.webp', animal: 'Chihuahua', breed: 'Chihuahua', style: 'Pixel Art' },
  { file: 'chihuahua_portrait_square_2048.jpg', animal: 'Chihuahua', breed: 'Chihuahua', style: 'Pixar 3D' },
  { file: 'golden_retriever_portrait_square.webp', animal: 'Golden Retriever', breed: 'Golden Retriever', style: 'Pixar 3D' },
  { file: 'pomeranian_portrait_final.webp', animal: 'Pomeranian', breed: 'Pomeranian', style: 'Needle Felt' },
  { file: 'shiba_inu_felt_portrait_2048x2048.webp', animal: 'Shiba Inu', breed: 'Shiba Inu', style: 'Needle Felt' },
  { file: 'shiba_inu_vinyl_toy_portrait_final.webp', animal: 'Shiba Inu', breed: 'Shiba Inu', style: 'Vinyl Toy' },
  { file: 'shiba_portrait_final_2048x2048.webp', animal: 'Shiba Inu', breed: 'Shiba Inu', style: 'Pixar 3D' },
  { file: 'shiba_portrait_final.webp', animal: 'Shiba Inu', breed: 'Shiba Inu', style: 'Needle Felt' },
  { file: 'white_pomeranian_portrait_final.webp', animal: 'Pomeranian', breed: 'Pomeranian', style: 'Pixar 3D' }
];

const selectedImage = galleryImages[Math.floor(Math.random() * galleryImages.length)];
const timestamp = new Date().toISOString();

return [{
  json: {
    selectedImage: selectedImage.file,
    animal: selectedImage.animal,
    breed: selectedImage.breed,
    style: selectedImage.style,
    timestamp: timestamp,
    imagePath: `/Users/michaelguo/pawcasso-atelier/website/public/gallery/${selectedImage.file}`,
    imageUrl: `https://pawcasso-atelier.vercel.app/gallery/${selectedImage.file}`
  }
}];

// Parse trending audio or use default
const audioData = $input.first().json;
let selectedAudio = {
  url: 'https://example.com/default-trending-sound.mp3',
  title: 'Trending Pet Sound',
  id: 'default'
};

// If API returns valid data, extract top trending sound
if (audioData && audioData.music_list && audioData.music_list.length > 0) {
  const topMusic = audioData.music_list[0];
  selectedAudio = {
    url: topMusic.play_url?.uri || selectedAudio.url,
    title: topMusic.title || selectedAudio.title,
    id: topMusic.id || selectedAudio.id
  };
}

// Merge with previous data
const previousData = $('Select Random Gallery Image').first().json;

return [{
  json: {
    ...previousData,
    audio: selectedAudio
  }
}];

// Generate caption using the caption generator script
const { execSync } = require('child_process');
const breed = $('Select Random Gallery Image').first().json.breed;
const style = $('Select Random Gallery Image').first().json.style;

// Call the caption generator script
try {
  const caption = execSync(
    `cd /Users/michaelguo/pawcasso-atelier/website && npx tsx scripts/generate-captions.ts "${breed}" "${style}"`,
    { encoding: 'utf-8' }
  ).trim();

  return [{
    json: {
      ...($input.first().json),
      caption: caption
    }
  }];
} catch (error) {
  // Fallback caption if script fails
  const fallbackCaption = `✨ POV: Your ${breed} becomes a ${style} masterpiece! 🎨\n\nCustom AI pet portraits just $9 💫\nLink in bio 👆\n\n#petportrait #${breed.toLowerCase().replace(' ', '')} #aiart #petlovers #doglovers #customart #petparent #dogsoftiktok`;

  return [{
    json: {
      ...($input.first().json),
      caption: fallbackCaption
    }
  }];
}

